package typeinfo

// PreserveAdaptiveEncoding returns the fresh TypeInfo with its storage encoding pinned to the encoding of the
// existing TypeInfo, when both represent the same variable-encoding type family. This prevents a freshly-constructed
// TypeInfo from silently adopting the global adaptive-encoding default (see UseAdaptiveEncoding) when the column was
// originally persisted under a legacy address encoding.
//
// It acts as a no-op (returns fresh unchanged) when:
//   - existing is nil,
//   - the two TypeInfos belong to different type families (e.g. VARCHAR -> TEXT, Point -> LineString), or
//   - the type family does not use variable adaptive encoding (e.g. integer types).
//
// It returns nil when fresh is nil.
//
// The SQL type semantics of fresh (e.g. character length, collation, SRID) are never modified; only the persisted
// storage encoding is carried over. Covered type families: string/text (blobStringType), binary/blob (varBinaryType),
// JSON (jsonType), and all concrete geometry types (pointType, linestringType, polygonType, multipointType,
// multilinestringType, multipolygonType, geomcollType, geometryType).
func PreserveAdaptiveEncoding(existing TypeInfo, fresh TypeInfo) TypeInfo {
	if fresh == nil {
		return nil
	}
	if existing == nil {
		return fresh
	}
	if !sameAdaptiveEncodingFamily(existing, fresh) {
		return fresh
	}
	return fresh.WithEncoding(existing.Encoding())
}

// sameAdaptiveEncodingFamily reports whether existing and fresh are the same concrete TypeInfo family that uses a
// variable storage encoding governed by UseAdaptiveEncoding. Geometry types are matched by their concrete type, so a
// change between two distinct geometry types (e.g. Point -> LineString) is treated as a family boundary.
func sameAdaptiveEncodingFamily(existing TypeInfo, fresh TypeInfo) bool {
	switch existing.(type) {
	case *blobStringType:
		_, ok := fresh.(*blobStringType)
		return ok
	case *varBinaryType:
		_, ok := fresh.(*varBinaryType)
		return ok
	case *jsonType:
		_, ok := fresh.(*jsonType)
		return ok
	case *pointType:
		_, ok := fresh.(*pointType)
		return ok
	case *linestringType:
		_, ok := fresh.(*linestringType)
		return ok
	case *polygonType:
		_, ok := fresh.(*polygonType)
		return ok
	case *multipointType:
		_, ok := fresh.(*multipointType)
		return ok
	case *multilinestringType:
		_, ok := fresh.(*multilinestringType)
		return ok
	case *multipolygonType:
		_, ok := fresh.(*multipolygonType)
		return ok
	case *geomcollType:
		_, ok := fresh.(*geomcollType)
		return ok
	case *geometryType:
		_, ok := fresh.(*geometryType)
		return ok
	default:
		return false
	}
}
