80	func ToDoltSchema(
81		ctx context.Context,
82		root doltdb.RootValue,
83		tableName doltdb.TableName,
84		sqlSchema sql.PrimaryKeySchema,
85		headRoot doltdb.RootValue,
86		collation sql.CollationID,
87	) (schema.Schema, error) {
88		var cols []schema.Column
89		var err error
90	
91		// generate tags for all columns
92		var names []string
93		var kinds []types.NomsKind
94		for _, col := range sqlSchema.Schema {
95			names = append(names, col.Name)
96			ti, err := typeinfo.FromSqlType(col.Type)
97			if err != nil {
98				return nil, err
99			}
100			kinds = append(kinds, ti.NomsKind())
101		}
102	
103		tags, err := doltdb.GenerateTagsForNewColumns(ctx, root, tableName, names, kinds, headRoot)
104		if err != nil {
105			return nil, err
106		}
107	
108		if len(tags) != len(sqlSchema.Schema) {
109			return nil, fmt.Errorf("number of tags should equal number of columns")
110		}
111	
112		for i, col := range sqlSchema.Schema {
113			convertedCol, err := ToDoltCol(tags[i], col)
114			if err != nil {
115				return nil, err
116			}
117			cols = append(cols, convertedCol)
118		}
119	
120		colColl := schema.NewColCollection(cols...)
121	
122		err = schema.ValidateForInsert(colColl)
123		if err != nil {
124			return nil, err
125		}
126	
127		sch, err := schema.NewSchema(colColl,
128			sqlSchema.PkOrdinals,
129			schema.Collation(collation),
130			nil,
131			nil,
132		)
133		if err != nil {
134			return nil, err
135		}
136	
137		return sch, nil
138	}
