351	func GenerateTagsForNewColumns(
352		ctx context.Context,
353		root RootValue,
354		tableName TableName,
355		newColNames []string,
356		newColKinds []types.NomsKind,
357		headRoot RootValue,
358	) ([]uint64, error) {
359		if len(newColNames) != len(newColKinds) {
360			return nil, fmt.Errorf("error generating tags, newColNames and newColKinds must be of equal length")
361		}
362	
363		newTags := make([]*uint64, len(newColNames))
364	
365		// Get existing columns from the current root, or the head root if the table doesn't exist in the current root. The
366		// latter case is to support reusing table tags in the case of drop / create in the same session, which is common
367		// during import.
368		existingCols, err := GetExistingColumns(ctx, root, headRoot, tableName, newColNames, newColKinds)
369		if err != nil {
370			return nil, err
371		}
372	
373		// If we found any existing columns set them in the newTags list.
374		for _, col := range existingCols {
375			for i := range newColNames {
376				// Only re-use tags if the noms kind didn't change
377				// TODO: revisit this when new storage format is further along
378				if strings.EqualFold(newColNames[i], col.Name) &&
379					newColKinds[i] == col.TypeInfo.NomsKind() {
380					newTags[i] = &col.Tag
381					break
382				}
383			}
384		}
385	
386		var existingColKinds []types.NomsKind
387		for _, col := range existingCols {
388			existingColKinds = append(existingColKinds, col.Kind)
389		}
390	
391		existingTags, err := GetAllTagsForRoots(ctx, headRoot, root)
392		if err != nil {
393			return nil, err
394		}
395	
396		outputTags := make([]uint64, len(newTags))
397		for i := range newTags {
398			if newTags[i] != nil {
399				outputTags[i] = *newTags[i]
400				continue
401			}
402	
403			outputTags[i] = schema.AutoGenerateTag(existingTags, tableName.Name, existingColKinds, newColNames[i], newColKinds[i])
404			existingColKinds = append(existingColKinds, newColKinds[i])
405			existingTags.Add(outputTags[i], tableName.Name)
406		}
407	
408		return outputTags, nil
409	}
