func TestScratchPreserve(t *testing.T) {
	old := UseAdaptiveEncoding
	UseAdaptiveEncoding = true
	defer func() { UseAdaptiveEncoding = old }()

	// existing nil -> fresh
	fresh := &blobStringType{sqlStringType: gmstypes.LongText}
	if got := PreserveAdaptiveEncoding(nil, fresh); got != TypeInfo(fresh) {
		t.Fatal("existing nil should return fresh")
	}
	// fresh nil -> nil
	if got := PreserveAdaptiveEncoding(fresh, nil); got != nil {
		t.Fatal("fresh nil should return nil")
	}
	// text legacy addr preserved, semantics kept
	existing := (&blobStringType{sqlStringType: gmstypes.Text}).WithEncoding(val.StringAddrEnc)
	got := PreserveAdaptiveEncoding(existing, fresh)
	if got.Encoding() != val.StringAddrEnc {
		t.Fatalf("want StringAddrEnc got %v", got.Encoding())
	}
	if got.ToSqlType().(interface{ MaxCharacterLength() int64 }).MaxCharacterLength() != gmstypes.LongText.MaxCharacterLength() {
		t.Fatal("semantics changed")
	}
	// binary
	eb := (&varBinaryType{sqlBinaryType: gmstypes.Blob}).WithEncoding(val.BytesAddrEnc)
	fb := &varBinaryType{sqlBinaryType: gmstypes.LongBlob}
	if PreserveAdaptiveEncoding(eb, fb).Encoding() != val.BytesAddrEnc {
		t.Fatal("bytes not preserved")
	}
	// json
	ej := (&jsonType{}).WithEncoding(val.JSONAddrEnc)
	if PreserveAdaptiveEncoding(ej, &jsonType{}).Encoding() != val.JSONAddrEnc {
		t.Fatal("json not preserved")
	}
	// geometry point
	ep := (&pointType{}).WithEncoding(val.GeomAddrEnc)
	if PreserveAdaptiveEncoding(ep, &pointType{}).Encoding() != val.GeomAddrEnc {
		t.Fatal("geom not preserved")
	}
	// different family: point -> linestring
	if got := PreserveAdaptiveEncoding(ep, &linestringType{}); got.Encoding() != val.GeomAdaptiveEnc {
		t.Fatalf("family boundary crossed: %v", got.Encoding())
	}
	// different family: varString -> blobString
	evs := &varStringType{sqlStringType: gmstypes.MustCreateStringWithDefaults(6 /*VarChar*/, 100)}
	_ = evs
	// integer: no adaptive
	if got := PreserveAdaptiveEncoding(Int64Type, Int64Type); got != TypeInfo(Int64Type) {
		t.Fatal("int should be unchanged")
	}
}
